import{_ as e,o as a,c as i,ah as r}from"./chunks/framework.D4KxWb5R.js";const f=JSON.parse('{"title":"Back-office Auticway","description":"","frontmatter":{},"headers":[],"relativePath":"guide/auticway.md","filePath":"src/guide/auticway.md"}'),o={name:"guide/auticway.md"};function s(d,t,c,n,u,l){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="back-office-auticway" tabindex="-1">Back-office Auticway <a class="header-anchor" href="#back-office-auticway" aria-label="Permalink to &quot;Back-office Auticway&quot;">​</a></h1><p>Auticway est le premier produit de M&#39;City. Son back-office s&#39;ouvre avec votre compte M&#39;City : pas de second mot de passe.</p><h2 id="se-connecter" tabindex="-1">Se connecter <a class="header-anchor" href="#se-connecter" aria-label="Permalink to &quot;Se connecter&quot;">​</a></h2><ol><li>Depuis votre <a href="./desk.html#acceder-a-un-back-office-produit">bureau</a>, ouvrez Auticway, ou allez sur la page de connexion du back-office et cliquez sur <strong>Se connecter avec M&#39;City</strong>.</li><li>Si vous n&#39;êtes pas connecté à M&#39;City, connectez-vous (avec votre double authentification).</li><li>Vous arrivez sur le tableau de bord d&#39;Auticway.</li></ol><p>Il faut, côté M&#39;City, un compte actif, le produit actif et un accès au back-office accordé (voir <a href="./administration/accounts.html">Comptes</a>). À la première connexion, un compte administrateur Auticway de même adresse e-mail est rattaché à votre compte M&#39;City ; à défaut, un compte est créé.</p><p>Vous déconnecter de M&#39;City vous déconnecte aussi d&#39;Auticway. Désactiver votre compte M&#39;City, ou vous retirer l&#39;accès, ferme aussitôt vos sessions Auticway.</p><h2 id="ce-que-vous-y-voyez" tabindex="-1">Ce que vous y voyez <a class="header-anchor" href="#ce-que-vous-y-voyez" aria-label="Permalink to &quot;Ce que vous y voyez&quot;">​</a></h2><p>Votre poste M&#39;City détermine votre rôle dans Auticway. Il est recalculé à chaque connexion : un changement de poste prend effet à la connexion suivante.</p><table tabindex="0"><thead><tr><th>Poste M&#39;City</th><th>Rôle Auticway</th><th>Pages</th></tr></thead><tbody><tr><td>PDG, Pôle Exploitation</td><td>admin-mcity</td><td>Toutes, sauf les rôles et les sessions (réservés au super-administrateur Auticway)</td></tr><tr><td>Pôle Support, Support N2</td><td>mcity-support</td><td>Tableau de bord, utilisateurs (modification), prestataires, offres, réservations, avis, alertes, diffusions, contenus</td></tr><tr><td>Support N1</td><td>mcity-support-n1</td><td>Tableau de bord, réservations, avis, alertes, utilisateurs (lecture seule)</td></tr><tr><td>Finance</td><td>mcity-finance</td><td>Tableau de bord, paiements, comptabilité, réservations</td></tr><tr><td>RH &amp; Juridique</td><td>mcity-hr</td><td>Tableau de bord, utilisateurs (modification, pour désactiver un compte)</td></tr></tbody></table><p>Un rôle restreint ne modifie que les comptes clients et prestataires, jamais les comptes d&#39;administration.</p><h2 id="messages-de-refus" tabindex="-1">Messages de refus <a class="header-anchor" href="#messages-de-refus" aria-label="Permalink to &quot;Messages de refus&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Que faire</th></tr></thead><tbody><tr><td>« Votre poste M&#39;City ne donne pas accès au back-office Auticway. Contactez votre administrateur M&#39;City. »</td><td>Votre compte n&#39;a pas de poste reconnu : demandez à l&#39;administrateur de vous en attribuer un.</td></tr><tr><td>« Ce compte est désactivé. »</td><td>Le compte Auticway est désactivé : contactez l&#39;administrateur Auticway.</td></tr><tr><td>« Cette adresse e-mail appartient à un compte qui n&#39;est pas un compte administrateur. »</td><td>L&#39;adresse est celle d&#39;un compte client ou prestataire d&#39;Auticway, ou d&#39;un compte déjà rattaché à un autre compte M&#39;City : demandez à l&#39;administrateur Auticway de régler le conflit.</td></tr><tr><td>Retour sur M&#39;City avec un refus d&#39;accès</td><td>L&#39;accès au back-office ne vous est pas accordé, ou le produit est inactif : voyez avec votre responsable de pôle.</td></tr></tbody></table><h2 id="notifications-du-back-office" tabindex="-1">Notifications du back-office <a class="header-anchor" href="#notifications-du-back-office" aria-label="Permalink to &quot;Notifications du back-office&quot;">​</a></h2><p>La cloche du back-office Auticway signale les événements à traiter, selon vos pages. Elle ouvre la liste complète et les <strong>Préférences</strong>, où vous choisissez, pour chaque événement, la notification dans le back-office et l&#39;e-mail. Les notifications sont supprimées après 90 jours.</p><table tabindex="0"><thead><tr><th>Événement</th><th>Page nécessaire</th><th>E-mail par défaut</th></tr></thead><tbody><tr><td>Prestataire à vérifier</td><td>Prestataires</td><td>Oui</td></tr><tr><td>Réservation en attente</td><td>Réservations</td><td>Non</td></tr><tr><td>Signalement d&#39;alerte</td><td>Alertes</td><td>Oui</td></tr><tr><td>Paiement échoué</td><td>Paiements</td><td>Oui</td></tr><tr><td>Export comptable échoué</td><td>Comptabilité</td><td>Oui</td></tr></tbody></table>',15)])])}const m=e(o,[["render",s]]);export{f as __pageData,m as default};
